/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    let res = {};
    const pageProps = api.context.props;
    debugger;
    if (Object.keys(pageProps).length > 0) {
        Object.keys(pageProps).forEach(propName => {
            if (pageProps[propName])
                res[propName] = pageProps[propName];
        });
    }
    return {
        propName: "pageParams",
        value: res
    };
}
